sections.text:
\begin{abstract}
Given a group $G$ and $V$ a representation of $G$, denote the number of indecomposable summands of $V^{\xx k}$ by $b_k^{G, V}$. 
   Given a tilting representation $T$ of $\SL_2(K)$ where $K=\overline{K}$ and of $\ch$ $p>2$, we show that $Ck^{-\alpha_p}(\dim T)^k<b_k^{T, \SL_2(K)}<Dk^{-\alpha_p}(\dim T)^k$ for some $C, D>0$ where $\alpha_p=1-(1/2)\log_p(\frac{p+1}{2}).$ 
\end{abstract}

\maketitle

Let $G$ be a group and $V$ be a representation of $G$. Decompose $V^{\otimes k}$ into indecomposables, and denote the number of direct summands of $V^{\xx k}$ by $b_k^{G, V}$. In \cite{coulembier2024growth}, Coulembier, Ostrik and Tubbenhauer showed $\lim_{k \to \infty} (b_k^{G, V})^{1/k}=\dim V.$ In \cite{coulembier2024fractalbehaviortensorpowers}, Coulembier, Etingof, Ostrik and Tubbenhauer proposed an asymptotic form $b_k^{G, V}$  
\begin{equation*}
    b^{G, V}_k \sim  h(k)k^{-\alpha} (\dim V)^k
\end{equation*}
where $h: \Z_{\ge 0} \to \R$ is bounded away from $0$ and $\infty$, and $\alpha \in \R_{\ge 0}$. 

In \cite{larsen2025tensorpowerasymptoticslinearly}, Larsen showed that when $G$ is linearly reductive over $K=\overline{K}$ of any characteristic and $V$ a faithful representation of $G$, the number $\alpha$ for $b_k^{G, V}$ is $u/2$ where $u$ is the dimension of the maximal unipotent subgroup of $G$. When $\alpha$ is transcendental or at least irrational, this is described as fractal behavior in \cite{coulembier2024fractalbehaviortensorpowers}.  We will soon see that when $G=\SL_2(K)$ where $K=\overline{K}$ is of positive characteristic, and $T$ is any tilting module of $G$, the corresponding $\alpha$ for $b_k^{G, T}$ are transcendental. 










When $G=\SL_2(K)$ where $K$ is algebraically closed and of $\ch$ $p>0$, and $V$ is the natural $2$-dimensional representation of $G$, the growth of $b_k^{G, V}$ has been studied in \cite{coulembier2024fractalbehaviortensorpowers} and \cite{larsen2024boundsmathrmsl2indecomposablestensorpowers} from two rather different directions. 

In \cite{coulembier2024fractalbehaviortensorpowers}, Coulembier, Etingof, Ostrik and
Tubbenhauer gave \begin{equation} \label{formofbounds}
    Ck^{-\alpha_p}2^k < b_k^{G, V}< D k^{-\alpha_p}2^k
\end{equation}
where $\alpha_p=1-(1/2)\log_p(\frac{p+1}{2}),$ which is a transcendental number, and proposed that $\alpha_p$ could be the fractal dimension of some fractal. 


In \cite{larsen2024boundsmathrmsl2indecomposablestensorpowers}, Larsen studied the case $p=2$, showed that $$b_{2k}^{G, V}\sim \omega(k)k^{-\alpha_2} 4^k$$ where  $\omega(x)$ is multiplicative periodic function,  and gave a lower bound of $b_k^{G, T}$ where $T$ is any tilting representation of $G$.

In this paper, we adopt the method in \cite{larsen2024boundsmathrmsl2indecomposablestensorpowers}, and use the  results from \cite{coulembier2024fractalbehaviortensorpowers}, to generalize  the results in \cite{coulembier2024fractalbehaviortensorpowers} and \cite{larsen2024boundsmathrmsl2indecomposablestensorpowers} and prove the following theorem.

\begin{thm}
    Let $T$ be a tilting representation of $\SL_2(K)$ where $K$ is algebraically closed and of $\ch$ $p>2$. Then there exist some positive numbers $C_T$ and $D_T$ such that when $k$ is sufficiently large, 

    \begin{equation} \label{main_ineq}
        C_Tk^{-\alpha_p} (\dim T)^k < b_k^{G, T}< D_T k^{-\alpha_p}(\dim T)^k    
    \end{equation}
    where $\alpha_p$ is as in \eqref{formofbounds}.     
\end{thm}

An indecomposable tilting module of $G$ is characterized by its highest weight. Let $T(n)$ denote the indecomposable tilting module of highest weight $n$. Define the generating function $$X_n(t)=\sum_{i\ge 0}a_{n, i}t^i$$ where $a_{n, i}$ is the multiplicity of $T(n)$ in $V^{\xx i}$. Then $b_k^{G, V}=\sum_{0 \le n \le k}a_{n, k}$.  We use a partial fraction expansion to understand the asymptotic behavior of $X_n(t)$, which enables us to use the equation \eqref{M_k} to reduce the approximation of $b_k^{G, T}$ to that of $b_l^{G, V}$ where $l$ is linear in $k$. We show that the generating functions $X_n(t)$ have two striking properties which are not obvious a priori. One is that $X_n(t)$ are rational functions, and the other is that  $X_n(t)$ are multiplicative in terms of base $p$ expansion. These properties lead us to use the partial fraction expansion on $X_n(t)$.









The paper is structured as follows. First, we fix notations and associate a generating function to each indecomposable tilting module.  In the second section, we recall the explicit decomposition of $T\xx V$ where $T$ is an indecomposable tilting module and $V$ is the natural representation of $\SL_2(K)$, and use this decomposition to obtain the properties of the generating functions. In the end, we use the estimations of the coefficients of the generating functions to give an upper bound and a lower bound of $b_k^{G, T}$ when $k$ is large.

\begin{thank}
    I would like to thank Michael Larsen for all of the comments, discussions and support, and Matthias Strauch for the encouragement. 
\end{thank}

Fix a prime $p>2$. For any non-negative integer $n$, the character $\chi_n(t)$ of $T(n)$ can be expressed in terms of the base $p$ expansion of $n+1$. Say, $n+1=a_j p^j+ a_{j-1}p^{j-1}+\cdots +a_0$ where $0 \le a_i<p$. 
Define the set $$\supp (n)= \{ a_j p^j \pm a_{j-1} p^{j-1} \pm \cdots \pm a_0\}$$ and the multiset $$\ext(n)=\{ x+1, x-1 \mid x \in \supp(n)\}.$$ 



By \cite[, Proposition 5.4]{tubbenhauer2021quivers}, \begin{equation} \label{char_n}
    \chi_n= \sum_{k \in \supp(n)} \frac{t^k-t^{-k}}{t-t^{-1}}.
\end{equation}

Since $(t^k - t^{-k})(t+t^{-1})=t^{(k+1)}-t^{-(k+1)}+t^{(k-1)}-t^{-(k-1)}$, \[ \chi_n \cdot \chi_1 = \sum_{k \in \ext(n)} \frac{t^k-t^{-k}}{t-t^{-1}}. \]


Define $T(-1)=\{0\}$ so that $\chi_{-1}$ satisfies the character formula.

\begin{prop} \label{decompT(m).T(1)}
Let $n$ be a non-negative integer, and write $n+1=[a_j, a_{j-1}, \ldots, a_0]$. 

Suppose $a_0 \neq p-1$, then  \begin{align*}
    T(n)\xx T(1)=\begin{cases}
        T(n+1) \quad \quad \quad \quad \quad \quad,a_0=0\\
        T(n+1)\oplus 2T(n-1) \ \  ,a_0=1\\
        T(n+1)\oplus T(n-1)\ \ \ , 1<a_0<p-1  \end{cases}
\end{align*}

        Suppose $a_0=p-1$. Let $d$ be the largest integer such that $p^{d+1} \mid n+2$ and $p^{d+2} \nmid n+2$, that is equivalent to saying $n+1=[a_j, \ldots,\   a_{d+1},\  p-1, \ldots, \ p-1]$ and $a_{d+1} \neq p-1$. 

        Then 
\begin{align*}
     &T(n)\xx T(1)=T(n+1)\oplus T(n-1) \oplus 
     \bigoplus_{i=1}^d T(n+1-2p^i)\\
     &\oplus \begin{cases}
             \begin{cases}
                0, \qquad \qquad \qquad \qquad \quad \ \ a_{d+1}=0\\
                T(n+1-2p^{d+1}), \quad 1<a_{d+1}<p-1\\
                2T(n+1-2p^{d+1}), \qquad \  a_{d+1}=1
            \end{cases}, n+2\neq ap^{d+1} \text{for some $0<a<p$} \\
 T(n+1-2p^{d+1}), \qquad \qquad \qquad \qquad \qquad \ \  n+2=ap^{d+1}, 1<a<p\\
 0, \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \quad \ \ n+2=p^{d+1} 
        \end{cases}
\end{align*}
       \end{prop}


The proposition gives Figure 1 and Figure 2 as subgraphs of the fusion graphs of $\xx V$ of the cases $p=3$ and $p=5$.

\usetikzlibrary{arrows.meta}









\begin{proof}
Finding the decomposition of $T(n) \xx T(1)$ is equivalent to writing $\ext(n)$ as a disjoint union of $\supp (m)$ for some $m$. If $\ext(n)= \sqcup_{m\in S} \supp(m) $, then $T(n)\xx T(1)=\oplus_{m \in S} T(m).$ 


Case 1) $a_0=0$:

Since $n+1= [a_j,\ a_{j-1}, \ldots,\ a_1,\ 0]$, we have $\ext(n)=\{ x+1, x-1 \mid x \in \supp(n)\}=\supp(n+1).$ \\

Case 2) $a_0=1$:

$\ext(n)= \supp (n+1) \sqcup_{i=1}^2 \supp(n-1).$\\

Case 3) $1<a_0<p-1$:

$\ext(n)=\supp(n+1) \sqcup \supp(n-1)$.\\

Case 4) $a_0=p-1$:

Write \[n+1=[a_j,\ a_{j-1}, \ldots,\ a_{d+1},\  p-1, \ldots, \ p-1, \ p-1].\] The analysis of $\ext(n)$ splits into the cases $d< j-1$ (i.e. $n+2\neq ap^{d+1}$ for some $0<a<p$), $d=j-1$  (i.e. $n+2=ap^{d+1}$ for some $1<a<p$), and $d=j$ (i.e. $n+2=p^{d+1})$.

Consider the case $d< j-1$,
\begin{align*}
    \ext(n)&= \{ [a_j,\ \pm a_{j-1}, \ldots,\ \pm  a_{d+1},\ \pm (p-1), \ldots,\ \pm (p-1), \ \pm p] \} \\
    &\sqcup \{ [a_j,\ \pm a_{j-1}, \ldots,\ \pm  a_{d+1},\ \pm (p-1), \ldots,\ \pm (p-1), \ \pm (p-2)] \}\\
    &=\{ [a_j,\ \pm a_{j-1}, \ldots,\ \pm  a_{d+1},\ \pm (p-1), \ldots, \ \pm (p-1), \ \pm p] \} \sqcup \supp(n-1).
\end{align*}

The set $\{[a_j,\ \pm a_{j-1}, \ldots,\ \pm  a_{d+1},\ \pm (p-1), \ldots, \ \pm (p-1), \ \pm p] \}$ is

\begin{equation} \label{1}
    \begin{aligned}
    \{  [a_j,\ \pm a_{j-1}, \ldots,\ \pm  &a_{d+1},\ \pm (p-1), \ldots,\ \pm (p-1), \ \mp (p-2), \ 0],\\
      [a_j,\ \pm a_{j-1}, \ldots,\ \pm  &a_{d+1},\ \pm (p-1), \ldots,\ \pm (p-1), \ \mp (p-2), \ 0, \ 0], \\
  &\vdotswithin{a_{d+1}}\\
[a_j,\ \pm a_{j-1}, \ldots,\ \pm & a_{d+1},\ \mp (p-2),\ 0, \ldots,  \ 0, \ 0],\\       
    [a_j,\ \pm a_{j-1}, \ldots,\  (\pm & a_{d+1})\pm 1,\ 0,\ 0, \ldots,  \ 0, \ 0]  
    \},
\end{aligned}
\end{equation}


where the elements in the $k$th row of (\ref{1}) are elements of the set  
\begin{align*}
  \{x+1 \mid x \in \supp (n) \text{ with the $i$-th digit of $x$ is $p-1$ for $0\le i<k$ and the $k$-digit is $-(p-1)$} \} \\
  \sqcup \{x-1 \mid x \in \supp (n) \text{ with the $i$-th digit of $x$ is $-(p-1)$ for $0\le i<k$ and the $k$-digit is $p-1$} \}.
\end{align*}

Therefore, 
\begin{align*}
 &\{[a_j,\ \pm a_{j-1}, \ldots,\ \pm  a_{d+1},\ \pm (p-1), \ldots, \ \pm (p-1), \ \pm p] \} \\
 = &\supp(n+1-2p)\sqcup \supp (n+1-2p^2) \sqcup \cdots \sqcup \supp(n+1-2p^d) \\ &\sqcup \{[a_j,\ \pm a_{j-1}, \ldots,\  (\pm a_{d+1})\pm 1,\ 0,\ 0, \ldots,  \ 0, \ 0]  
    \}. 
\end{align*}
The set 
\begin{align*}
        &\{[a_j,\ \pm a_{j-1}, \ldots,\  (\pm a_{d+1})\pm 1,\ 0,\ 0, \ldots,  \ 0, \ 0]  
    \}\\
    &=\supp(n+1) \sqcup \begin{cases}
         \varnothing,\ \text{when } a_{d+1}=0 \\
        \supp(n+1-2p^{d+1}),\ \text{when } 2\le a_{d+1}<p-1\\
        \sqcup_{i=1}^2 \supp(n+1-2p^{d+1}),\ \text{when } a_{d+1}=1.
    \end{cases}
\end{align*}

A similar argument applies to the case $d=j-1$ where the set of the elements in the last row of ($\ref{1}$) is $$\{[a_{d+1}\pm 1,\ 0, \cdots, \ 0]\}=\supp(n+1) \sqcup \supp (n+1-2p^{d+1}),$$ and the case $d=j$ where the set of the elements in the last row of ($\ref{1}$) is $$\{[(p-1)\pm 1,\ 0, \cdots, \ 0]\}=\supp(n+1) \sqcup \supp(n+1-2p^d).$$

Hence, 
\begin{align*}
    \ext(n)&=\supp(n+1) \sqcup \supp (n-1) \sqcup \sqcup_{i=1}^d \supp(n+1-2p^i)\\
    &\sqcup \begin{cases}
        \begin{cases}
         \varnothing,\ & a_{d+1}=0 \\
        \supp(n+1-2p^{d+1}),\ & 2\le a_{d+1}<p-1\\
        \sqcup_{i=1}^2 \supp(n+1-2p^{d+1}),\ & a_{d+1}=1\end{cases}\ &\text{when } d<j-1,\\    
\supp(n+1-2p^{d+1}),\ &\text{when } d=j-1,\\
\varnothing,\ &\text{when } d=j. \end{cases}
\end{align*}
\end{proof}

\begin{lemma} \label{lineareqofX_n}
    Given $n\in \Z_{\ge 0}$, write $n+1=[a_j,\ a_{j-1},\ \ldots,\ a_0].$
    Set $X_{-1}=1/t$. 
    The generating functions $X_n$ satisfy the following linear equations.  

When $a_0 \neq 0$,
\begin{equation} \label{eq3}
X_n=
    \begin{cases}
        t(X_{n-1}+X_{n+1}), \text{ when } 1 \le a_0 < p-1,\\
        t X_{n-1}, \text{when } a_0=p-1.\\
        \end{cases}
\end{equation}

When $a_0=0$,
\begin{equation} \label{eq2}  
\begin{aligned} 
    X_n&=t(X_{n-1}+2X_{n+1}+\sum_{i=1}^d 2X_{n+2p^i-1})\\
    &+\begin{cases}
        0,\ &n+1\equiv (p-1)p^{d+1} 
\quad  \text{(mod $p^{d+2}$)}\\
        tX_{n-1+2p^{d+1}},\ &n+1\equiv ap^{d+1},\ 1\le a \le p-2 \quad \text{(mod $p^{d+2}$)} 
        \end{cases} 
\end{aligned}
   \end{equation}
\end{lemma}

\begin{proof}

By the definition of the generating function $X_n$, $$X_n=t(\sum_m c_mX_m),$$ where $c_m$ is defined so that  $T(n)$ is a direct summand of $T(m)\xx T(1)$ with multiplicity $c_m>0$.

Suppose $n+1\ge p$ and write $n+1=[a_j,\ a_{j-1},\ \ldots,\ a_0].$
By Proposition \ref{decompT(m).T(1)}, it follows
\begin{align*}
    X_n&=t(X_{n-1}+X_{n+1}), \text{ when } 1 \le a_0 < p-1, \\
    X_n&=t X_{n-1}, \text{when } a_0=p-1.
\end{align*}

When $a_0=0$, $X_n=t( X_{n-1}+2X_{n+1}+\sum_m c_mX_m)$ where $m+1-2p^k=n$ for some $k$. It suffices to find all such $k$. The proof splits into the case that $n+1=ap^{l+1}$ for some $0<a<p$ and the case that $n+1 \neq ap^{l+1}$ for some $0<a<p$. 

Case 1) $n+1=ap^{l+1}$:  

The base $p$ expansion of $n+1$ is $[a,\ 0, \cdots, \ 0]$ where the leftmost digit is the digit in position $l+1$. By assumption, $$m+1=n+2p^k.$$

Suppose $k \le l$. Then $m+1=[a,\ 0, \cdots, 0,\ 1,\ p-1, \cdots, \ p-1]$ where $1$ is the $k$-th digit. Then $T(n)$ is a direct summand of $T(m)$ with multiplicity $2$ by Proposition $\ref{decompT(m).T(1)}$ with $d=l$.\\ 

Suppose $k=l+1$, $m+1=[a+1,\  p-1, \cdots, \ p-1]$. Then $T(n)$ is a direct summand of $T(m)$ with multiplicity $1$ when $1\le a \le p-2$.\\

Suppose $k>l+1$, $T(n)$ is not a direct summand of $T(m)\xx T(1)$.
\\

Therefore, 
\begin{align*}
    X_n&=t(X_{n-1}+2X_{n+1}+\sum_{i=1}^l 2X_{n+2p^i-1})\\
    &+\begin{cases}
        0,\ n+1=(p-1)p^{l+1}\\
        tX_{n+2p^{l+1}-1},\ n+1=ap^{l+1},\ 1\le a \le p-2.
\end{cases}
\end{align*}



Case 2) $n+1 \neq ap^{l+1}$ for all $0<a<p$:

The assumption gives that the base $p$ expansion of $n+1$ has at least two initial non-zero digits. Say $$n+1=[a_j,\ \cdots, \ a_{d+1},\ 0, \cdots, \ 0],$$ where $d+1<j$ and $a_{d+1}\neq0$. Consider $m+1=n+2p^k$ for some $k$.\\

If $k \le d$, then $m+1=[a_j, \cdots, \ a_{d+1},\ 0, \cdots,\ 0, \ 1,\ p-1, \cdots, \ p-1]$ where $1$ is the $k$-th digit and $T(n)$ is a direct summand of $T(m)\xx T(1)$ with multiplicity $2$.
\\

If $k=d+1$, $m+1=[a_j, \cdots, \ a_{d+1}+1,\ p-1, \cdots, \ p-1],$ and \begin{align*}
    T(m)\xx T(1)=&T(m+1) \oplus T (m-1) \oplus \bigoplus_{i=1}^dT(m+1-2p^i)\\
    &\oplus \begin{cases}
        0, &a_{d+1}+1=0 \Leftrightarrow a_{d+1}=p-1\\
        2T(m+1-2p^{d+1}), &a_{d+1}+1=1 \Leftrightarrow a_{d+1}=0\\
        T(m+1-2p^{d+1}), &1<a_{d+1}+1 \le p-1 \Leftrightarrow 1 \le a_{d+1} \le p-2.
    \end{cases}
\end{align*}
The case $a_{d+1}=0$ is not possible by the assumption on $n+1$.
\\

If $k>d+1$, $T(n)$ is not a direct summand of $T(m)\xx T(1)$.

Therefore, \begin{align*}
    X_n&=t(X_{n-1}+2X_{n+1}+\sum_{i=1}^d 2X_{n+2p^i-1})\\
    &+\begin{cases}
        0,\ &n+1\equiv (p-1)p^{d+1} 
\quad  \text{(mod $p^{d+2}$)}\\
        tX_{n+2p^{d+1}-1},\ &n+1\equiv ap^{d+1},\ 1\le a \le p-2 \quad \text{(mod $p^{d+2}$)}.
\end{cases}
\end{align*}

Combining both cases, one has the equation \eqref{eq2}.
\end{proof}


Using Lemma \ref{lineareqofX_n} and the method to get (2.6) in \cite{larsen2024boundsmathrmsl2indecomposablestensorpowers}, and defining $Z_n=X_{n-1}$, one has the following multiplicative formula 

\begin{prop} \label{ap^s+n=ap^s+n}
    For $0\le a<p$, $\ s \ge 0$, and $0 \le i < p^s$, then
    $$Z_{ap^s+i}=tZ_{ap^s}Z_i.$$    
\end{prop}

\begin{proof}



Given $s\in \N$, for $0 \le n \le p^s-1$, consider the set of linear forms $L_n^s$ in the $p^s+1$ variables $y_i$, $0 \le i \le p^s$ and

\begin{equation*}
     L_n^s(y_{0}, \cdots, y_{p^s-1})
     =\begin{cases}
         t(y_{n-1}+y_{n+1}), \text{ when } \ p \nmid n(n+1),\\
         t y_{n-1}, \text{when } p \mid n+1,\\         
         t(y_{n-1}+2y_{n+1}+\sum_{i=1}^d 2y_{n+2p^i-1})
    \\
    +\begin{cases}
        0,\ n+1=(p-1)p^{d+1}\\
        ty_{n-1+2p^{d+1}},\ n+1=ap^{d+1},\ 1\le a \le p-2, 
        \end{cases} 
        \text{ when }p \mid n.
        \\        
     \end{cases}
 \end{equation*}

Let $L^s(y_{0}, \cdots, y_{p^s-1})$ be the linear system $L_n^s(y_{0}, \cdots, y_{p^s-1})-y_n=0$ for $1 \le n \le p^s-1$. Then $L^s(y_{0}, \cdots, y_{p^s-1})$ gives a $(p^s-1) \times p^s$ matrix $A^s$ of rank $p^s-1$ as the rank of $A^s$ (mod $t\Q(t)$) is of rank $p^s-1$.




As both $(Z_{0},\ Z_0,\cdots,\ Z_{p^{s}-1})$ and $(Z_{ap^{s}},\ Z_{ap^{s}+1},\cdots,\ Z_{(a+1)p^{s}-1})$ are solutions of $L^s$, $$(Z_{ap^{s}},\ Z_{ap^{s}+1},\cdots,\ Z_{(a+1)p^{s}-1})=q(t)(Z_{0},\ Z_1,\cdots,\ Z_{p^{s}-1})$$ for some $q(t) \in \Q(t)$. Since $Z_{ap^{s}}=q(t) Z_{0}$ and $Z_{0}=1/t$, it follows that $q(t)=t Z_{ap^{s}}$ and $$Z_{ap^s+i}=tZ_{ap^s}Z_i$$ for $0\le i< p^s$. 

 \end{proof}

In the following, we work with the generating functions $Z_n=X_{n-1}$, and $Z_0=1/t$.




\begin{lemma} \label{Z_p^s relations}
    Given $s \ge0$, define     $c_s= \frac{tZ_{p^s}}{1+tZ_{2p^s}}$. Then \begin{equation} \label{Z_ap^s_back_forth}
    Z_{ap^s}=\begin{cases}
        c_s (Z_{(a-1)p^s}+Z_{(a+1)p^s}),\ 1\le a \le p-2\\
        c_sZ_{(p-2)p^s}, a=p-1.
    \end{cases}        
    \end{equation}

\end{lemma}



\begin{proof}
When $s=0$, by the definition, $c_0=tZ_1/(1+tZ_2)$, which is equal to $t$ as $Z_1=X_0=1+tX_1=1+tZ_2=t(1/t+Z_2)$. Therefore, the equation \eqref{Z_ap^s_back_forth}
holds from the decomposition of $T(n)\xx T(1)$ for $p>n \ge 0.$

Suppose $s \ge 1$. 

For $a=1$, the formula holds since $Z_0=1/t$.

For $a>1$, we begin with two observations from the multiplicative property, 

\begin{equation} \label{ob_1}
    Z_{kp^s+n}Z_{lp^s}=Z_{kp^s}Z_{lp^s+n}
\end{equation}
when $0 < n \le p^s$ and 
\begin{equation} \label{ob_2}
    Z_{kp^s-n} Z_{lp^s}=Z_{(k-1)p^s+(p^s-n)} Z_{lp^s}=Z_{(k-1)p^s}Z_{(l+1)p^s-n}
    \end{equation}
    when $1\le k \le p$, $1 \le l <p$ and $0< n \le  p^s$.


For any $a \le p-2$ and $s>0$, by (\ref{eq2}), $$Z_{ap^s}=t(Z_{ap^s-1}+\sum_{i=0}^{s-1}2Z_{ap^s+2p^i-1}+Z_{ap^s+2p^s-1}).$$

Multiplying both sides by $Z_{p^s}$, then \begin{align*}
    Z_{p^s}Z_{ap^s}&=tZ_{p^s}Z_{ap^s-1}+tZ_{p^s}\sum_{i=0}^{s-1}2Z_{ap^s+2p^i-1}+tZ_{p^s}Z_{ap^s+2p^s-1}\\
    &\stackrel{(i)}{=}  tZ_{p^s}Z_{ap^s-1}+tZ_{ap^s}\sum_{i=0}^{s-1}2Z_{p^s+2p^i-1}+tZ_{(a+1)p^s}Z_{2p^s-1}\\ 
    &\stackrel{(ii)}{=}  tZ_{p^s}Z_{ap^s-1}+Z_{ap^s}(Z_{p^s}-tZ_{p^s-1}-tZ_{3p^s-1})+tZ_{(a+1)p^s}Z_{2p^s-1},
\end{align*}

where $(i)$ comes from \eqref{ob_1} and \eqref{ob_2}, and $(ii)$ comes from $$Z_{p^s}=t(Z_{p^s-1}+\sum_{i=0}^{s-1} 2Z_{p^s+2p^i-1}+Z_{p^s+2p^s-1}).$$


