For any $m\in \N$, let $M_m$ be the $m\times m$ matrix with $1$ along the main diagonal and $-t$ along the first diagonal above and below the main diagonal. Let $P_m(t)=\det M_m$, and $P_0(t)=1.$


\begin{prop} \label{Z_ap^s}
Given $s \ge 0$, for $0 \le a <p$,
  $$Z_{ap^s}=\frac{1}{t} \frac{c_s^{a}P_{p-a-1}(c_s)}{P_{p-1}(c_s)}.$$

  In particular, $$Z_{a}=\frac{1}{t} \frac{t^{a}P_{p-a-1}(t)}{P_{p-1}(t)}.$$
\end{prop}

\begin{proof}
    Given $s\ge 0$, consider a $p\times p$ matrix $M=\begin{pmatrix}
        A &B\\
        C &D
    \end{pmatrix}$ where the block $D$ is obtained by substituting $t=c_s$ in the matrix $M_{p-1}$, the block matrix $A=(1)$, the block $B$ is a zero row and the block $C$ is a column with $-c_s$ as its the first entry and $0$ for the remaining entries. As the column vector $\begin{pmatrix}
            Z_0, Z_{p^s}, \ldots,             Z_{(p-1)p^s}
        \end{pmatrix}$ is the solution of $M \vec{x} =\begin{pmatrix}
        1/t,  0, \ldots,         0
        \end{pmatrix}$ by Lemma $\ref{Z_p^s relations}$, it follows that $\begin{pmatrix}
             Z_0, Z_{p^s}, \ldots,             Z_{(p-1)p^s}
        \end{pmatrix}=M^{-1} \begin{pmatrix}
        1/t,  0, \ldots,         0
        \end{pmatrix}.$

By the definition of $M$, it follows that $\det M_{1, k}= (-c_s)^{k-1}P_{p-k}(c_s)$. Hence, the $(k, 1)$-th entry of $M^{-1}$ is $$(\det M)^{-1} (-1)^{k+1}(-c_s)^{k-1}P_{p-k}(c_s)=(P_{p-1}(c_s))^{-1}c_s^{k-1}P_{p-k}(c_s).$$ Therefore, $$Z_{ap^s}=(1/t)(c_s^{a}P_{p-a-1}(c_s)/P_{p-1}(c_s)).$$
\end{proof}

The Proposition \ref{Z_ap^s} gives the following result
\begin{lemma}\label{functionF}
    For $1 \le a <p$, define $F_a(t)=t^aP_{p-a-1}(t)/P_{p-1}(t)= tZ_a(t)$. For any non-negative integer $s$, $$tZ_{ap^s}=F_a(c_s)=c_s Z_a(c_s).$$
\end{lemma}

Recall that $Z_n=X_{n-1}=\sum_{i=0}^\infty a_i t^i$ is the generating function associated to $T(n-1)$ so it is a function in $t$. Therefore, the function $c_s=tZ_{p^s}/(1+tZ_{2p^s}) $ is a function in $t$. Abusing notations, we write $Z_n(t)$ as $Z_n$ and $c_s(t)$ as $c_s$ when the fact that they are functions in the variable $t$ is not relevant. The notations $Z_n(c_i)$ ($c_s(c_i)$, resp.) for some $i$ denote the functions $Z_n(t)$ ($c_s(t)$, resp.) evaluated at $t=c_i$.

The next lemma relates $c_s$ to certain functions $Z_n$
with $n<p^s$ and it will be used to prove the iterative relation $c_s=c_1(c_{s-1})$.

\begin{lemma} \label{expression of c_s}
    For $s\ge 0$, the function $c_s$ is equal to $$\frac{t^2Z_{p^s-1}}{1-2t^3\sum_{i=0}^{s-1}Z_{p^i}Z_{p^i-1}}.$$ 
\end{lemma}

\begin{proof}
    Lemma \ref{Z_p^s relations} gives \begin{equation*}
    Z_{(p-1)p^s}=c_sZ_{(p-2)p^s}.
\end{equation*}

By (\ref{eq2}) and Proposition \ref{ap^s+n=ap^s+n}, 
    \begin{align} \label{eq6}
\nonumber        
        Z_{(p-1)p^s}&=t(Z_{(p-1)p^s-1}+ \sum_{i=0}^{s-1} 2Z_{(p-1)p^s+2p^i-1})\\ 
\nonumber
        &=t(Z_{(p-2)p^s+p^s-1}+ \sum_{i=0}^{s-1} 2Z_{(p-1)p^s+2p^i-1})\\
        &=t(tZ_{(p-2)p^s}Z_{p^s-1}+ \sum_{i=0}^{s-1} 2tZ_{(p-1)p^s}Z_{2p^i-1}).
    \end{align}



Substituting $ Z_{(p-1)p^s}=c_sZ_{(p-2)p^s}$ into (\ref{eq6}) and dividing it by $ Z_{(p-2)p^s}$, one gets

\begin{align*}
    c_s&=t(tZ_{p^s-1}+2tc_s \sum_{i=0}^{s-1}Z_{2p^i-1})\\
    &=t(tZ_{p^s-1}+2tc_s \sum_{i=0}^{s-1}tZ_{p^i}Z_{p^i-1})\\
    &=t^2Z_{p^s-1}+2t^3c_s\sum_{i=0}^{s-1}Z_{p^i}Z_{p^i-1}.
\end{align*}

Therefore, $(1-2t^3\sum_{i=0}^{s-1}Z_{p^i}Z_{p^i-1})c_s=t^2Z_{p^s-1}$ and \begin{equation*}
    c_s=\frac{t^2Z_{p^s-1}}{1-2t^3\sum_{i=0}^{s-1}Z_{p^i}Z_{p^i-1}}.     
\end{equation*}
\end{proof}


\begin{prop} \label{s=1+s-1}
