\end{prop}

\begin{proof}
    We prove it by induction on $s$.

    When $s=1$, it holds as $c_0=t$.

    Let $s>1$.    
    By the induction hypothesis,  $c_k(t)=c_1(c_{k-1})$ for all $k \le s-1$.

    Since $tZ_{ap^k}(t)=F_a(c_k(t))$ by Lemma \ref{functionF} and by the induction hypothesis, it follows that when $k \le s-1$, $$        c_1Z_{ap^{k-1}}(c_1)=F_a(c_{k-1}(c_1))=F_a(c_k)=tZ_{ap^k}(t).    $$ Therefore, given  $n$ an integer , $1\le n <p^{s-1}$,  Proposition \ref{ap^s+n=ap^s+n}  and the identity $c_k(t)=c_1(c_{k-1})$ imply 
\begin{equation}\label{c_1.levels.up}
    c_1Z_{n}(c_1)=tZ_{pn}(t).
\end{equation}

By Lemma \ref{expression of c_s}, $$c_s(t)=\frac{t^2Z_{p^s-1}(t)}{1-2t^3\sum_{i=0}^{s-1}Z_{p^i}(t)Z_{p^i-1}(t)}.$$
Hence, 

\begin{align*}
    c_s(c_1)&=\frac{c_1^2Z_{p^s-1}(c_1)}{1-2c_1^3\sum_{i=0}^{s-1}Z_{p^i}(c_1)Z_{p^i-1}(c_1)}\\
    &=\frac{c_1(c_1Z_{p^s-1}(c_1))}{1-2c_1\sum_{i=0}^{s-1}c_1Z_{p^i}(c_1)c_1Z_{p^i-1}(c_1)}\\
    &=\frac{c_1tZ_{p^{s+1}-p}(t)}{1-2c_1\sum_{i=0}^{s-1}tZ_{p^{i+1}}(t)tZ_{p^{i+1}-p}(t)}.
\end{align*}

Substitute $c_1=\frac{t^2Z_{p-1}}{1-2t^3Z_1Z_0}$ into the right hand side of the above equation and multiply the numerator and the  denominator by $1-2t^3Z_1 Z_0$. Then \begin{align*}
c_s(c_1)&=\frac{tZ_{p^{s+1}}t^2Z_{p-1}}{1-2t^3Z_1Z_0-2t^2Z_{p-1}\sum_{i=0}^{s-1}tZ_{p^{i+1}}tZ_{p^{i+1}-p}}\\
&\stackrel{(i)}{=}  \frac{tZ_{p^{s+1}}t^2Z_{p-1}}{1-2t^3Z_1Z_0-2t^3\sum_{i=0}^{s-1}Z_{p^{i+1}}(tZ_{p^{i+1}-p}Z_{p-1})}\\
&\stackrel{(ii)}{=}\frac{tZ_{p^{s+1}}t^2Z_{p-1}}{1-2t^3Z_1Z_0-2t^3\sum_{i=0}^{s-1}Z_{p^{i+1}}Z_{p^{i+1}-1}}\\
&=\frac{tZ_{p^{s+1}}t^2Z_{p-1}}{1-2t^3\sum_{i=0}^{s}Z_{p^{i}}Z_{p^{i}-1}},
\end{align*}
where (i) comes from moving $Z_{p-1}$ in the denominator into the summation and (ii) comes from the multiplicative property of generating functions $Z_n$.

Then the result follows from Lemma \ref{expression of c_s}. 
    \end{proof}



For any $n\in \N$, let $Q_n(x)$ be the polynomial of degree $n$ so that $Q_n(2\cos \theta)=2\cos n \theta$, equivalently, $Q_n(t+t^{-1})=t^n+t^{-n}$. Let $T_n(x)$ be the Chebyshev polynomials of the first kind, i.e., $T_n(\cos x)= \cos nx$. Hence, $Q_n(x)=2T_n(x/2)$. When we use the term Chebyshev polynomials in this article, we use $Q_n(x)$ instead of $T_n(x).$

Recall that the prime $p>2$ is the characteristic of the algebraically closed field in the setting. Our goal is to relate $c_1(t)$ to $Q_p(t)$.

\begin{prop}
The function $c_1(t)=(Q_p(1/t))^{-1}$.
\end{prop}

\begin{proof}
    Since $tZ_1(t)=tP_{p-2}(t)/P_{p-1}(t)$ and $tZ_{p-1}(t)=t^{p-1}/P_{p-1}(t)$, by Lemma \ref{expression of c_s}, $$c_1(t)=\frac{t^2Z_{p-1}}{1-2t^2Z_1}=\frac{t(t^{p-1}/P_{p-1}(t))}{1-2t(tP_{p-2}(t)/P_{p-1}(t))}=\frac{t^p}{P_{p-1}(t)-2t^2P_{p-2}(t)}.$$


    Let $A_n(t)=P_{n-1}(t)-2t^2P_{n-2}(t)$, and $F_n(1/t)=(1/t^n)A_n(t)$. Since $c_1(t)=(F_p(1/t))^{-1}$, it suffices to show $F_p(t)=Q_p(t).$

    Let $P_0(t)$=1. By the definition of $P_n(t)$ and expansion by minors, one has $$P_n(t)=P_{n-1}(t)-t^2P_{n-2}(t)$$ when $n>1$. Since $A_n(t)$ is a linear combination of $P_{n-1}(t)$ and $P_{n-2}(t)$ (with coefficients in $\Q(t)$), $$A_n(t)=A_{n-1}(t)-t^2A_{n-2}(t).$$

    Hence, \begin{align*}
        F_n(t)&=t^nA_n(1/t)\\
        &=t^n(A_{n-1}(1/t)-t^{-2}A_{n-2}(1/t))\\
        &=t\cdot t^{n-1}A_{n-1}(1/t)-t^{n-2}A_{n-2}(1/t)\\
        &=tF_{n-1}(t)-F_{n-2}(t).
    \end{align*}

