       \item[(1)]  when $k \ge d,$  the $t^k$-coefficient of $g(t)/\hat{f}(t)$ is $$\sum_{\{ \b \mid f(\b)=0  \}}  \frac{\b^{n-1}}{f'(\b)}g(\b^{-1})\b^k.$$

       \item [(2)]  When $k<d$, the $t^k$-coefficient of $g(t)/\hat{f}(t)$ is $$\sum_{\{ \b \mid f(\b)=0  \}} \frac{\b^{n-1}}{f'(\b)}\sum_{0 \le i \le k} a_i\b^{k-i}.$$
   \end{itemize}



\end{lemma}

\begin{proof}
    \begin{itemize}
        \item [(1)]By Lemma \ref{1/hat}, $$\frac{g(t)}{\hat{f}(x)}=g(t)\sum_{\{ \b \mid f(\b)=0  \}} \frac{\beta^{n-1}}{f'(\beta)(1-\beta  t)}=\sum_{\{ \b \mid f(\b)=0  \}} \frac{\beta^{n-1}}{f'(\beta)}(a_dt^d+\cdots+a_0)(1+\b t+\b^2t^2+\cdots).$$

    Therefore, when $k \ge d$, the $t^k$-coefficient of $g(t)/\hat{f}(x)$ is $$\sum_{\{ \b \mid f(\b)=0  \}} \frac{\b^{n-1}}{f'(\b)}\sum_{0 \le i \le d} a_i\b^{k-i}=\sum_{\{ \b \mid f(\b)=0  \}} \frac{\b^{n-1}}{f'(\b)} g(\b^{-1}) \b^k.$$

        \item [(2)] follows by the same reasoning as (1) since only non-negative powers of $\b$ can appear in the sum.    
    \end{itemize}    
\end{proof}



