\begin{prop} \label{R_m-1}
    For any $\theta \in \R,$ $$R_{m-1}(2\cos \theta)=\frac{2\sin m (\theta-\pi)}{\sin \theta}=\begin{dcases}
        \frac{2\sin m \theta}{\sin \theta} \qquad \text{ if $m$ is even}\\
        \frac{-2\sin m \theta}{\sin \theta} \qquad \text{ if $m$ is odd}.
    \end{dcases}$$
\end{prop}

\begin{proof}
    Define $\widetilde{R}_{m-1}(t)=\prod_{k=0}^{m-1}(t-2\cos k\pi/m)=R_{m-1}(t)\cdot(t-2).$  By the sum-to-product identity, \begin{align*}
        (\cos \theta- \cos k\pi/m)&=-2\sin(\frac{\theta}{2}+\frac{k\pi}{2m})\sin (\frac{\theta}{2}-\frac{k\pi}{2m})\\
        &=-2 \sin (\frac{\theta - \pi}{2}+\frac{(m+k)\pi}{2m})\sin (\frac{\theta - \pi}{2}+\frac{(m-k)\pi}{2m}).
    \end{align*}


    Hence, \begin{align*}
    \widetilde{R}_{m-1}(2\cos \theta)&=(-4)^m \prod_{k=0}^{m-1}\sin(\frac{\theta - \pi}{2}+\frac{(m+k)\pi}{2m})\sin(\frac{\theta - \pi}{2}+\frac{(m-k)\pi}{2m})\\
    &=(-4)^m \Big(\prod_{k=0}^{2m-1}\sin(\frac{\theta - \pi}{2}+\frac{k\pi}{2m})\Big)\sin(\frac{\theta - \pi}{2}+\frac{\pi}{2}) \big/ \sin(\frac{\theta - \pi}{2}+\frac{0\pi}{2m})\\
    &=(-4)^m \big(\prod_{k=0}^{2m-1}\sin(\frac{\theta - \pi}{2}+\frac{k\pi}{2m})\Big) (-\tan(\frac{\theta}{2})).
    \end{align*}

By \eqref{sin_identity}, 
\begin{align*}
\widetilde{R}_{m-1}(2\cos \theta)&= (-4)^{m} 2^{-(2m-1)} \sin (2m(\theta-\pi)/2) (-\tan(\theta/2))\\
&=-2 \sin (m(\theta-\pi)) \tan(\theta/2)
\end{align*}


As $R_{m-1}(2\cos \theta)=\widetilde{R}_{m-1}(2\cos \theta)(2\cos \theta-2\cos 0)^{-1}$ and $(2\cos \theta-2\cos 0)=-2\sin^2(\theta/2)$, the result follows.
\end{proof}


\begin{lemma} \label{R'p-1}
    Suppose $2\cos \theta$ is a root of $R_{p-1}(t)$, i.e. $\theta=k\pi/p$ for some $0<k<p$. Then $$R_{p-1}'(2\cos \theta)=(-1)^k \frac{p}{2\sin^2 \theta}.$$
\end{lemma}

\begin{proof}

    Let $\zeta=\zeta_{2p}=e^{i \pi/p}.$ Hence, $2\cos \theta= \zeta^k+\zeta^{-k}.$

    \begin{align*}
        R_{p-1}'(2\cos \theta)&= \prod_{l \neq k, \text{ and } 0<l<p}(\zeta^k + \zeta^{-k}-\zeta^l - \zeta^{-l})\\
        &=\prod_{l \neq k}\zeta^{-k}(1-\zeta^{k+l})(1-\zeta^{k-l})\\
        &=\zeta^{-k(p-2)}\Big(\prod_{l=1}^{2p-1}(1-\zeta^l)\Big)(1-\zeta^{2k})^{-1}(1-\zeta^k)^{-1}(1-\zeta^{p+k})^{-1}\\
        &=\zeta^{-k(p-2)}\Big(\prod_{l=1}^{2p-1}(1-\zeta^l)\Big)(1-\zeta^{2k})^{-2}\\
        &=\zeta^{-k(p-2)}\Big(\prod_{l=1}^{2p-1}(1-\zeta^l)\Big)\zeta^{-2k}(\zeta^{-k}-\zeta^k)^{-2}\\
        &=\zeta^{-kp}\frac{2p}{(2\sin \theta)^2}
        =(-1)^k \frac{p}{2 \sin ^2 \theta}.
    \end{align*}
\end{proof}

\begin{lemma} \label{R_p-1,s'}
    Suppose $\theta_0$ is an angle such that  $R_{p-1,i}(2\cos \theta_0)=0$. Hence, $p^i \theta_0=k\pi/p$ for some $k$ where $p>k>0.$  Then $$R_{p-1,i}'(2\cos \theta_0)=(-1)^k \frac{p^{i+1}}{2\sin (p^i\theta_0) \sin \theta_0}.$$
\end{lemma}

\begin{proof}
    Since $R_{p-1,i}(t)=R_{p-1}(Q_{p^i}(t)),$ it follows $$R_{p-1,i}'(2\cos \theta)=R_{p-1}'(Q_{p^i}(2\cos \theta))\cdot Q_{p^i}'(2 \cos \theta).$$

    Let $F(\theta)= Q_{p^i}(2\cos \theta)=2\cos (p^i \theta)$. By the chain rule,  $$F'(\theta)=Q_{p^i}'(2\cos \theta) \cdot (-2\sin \theta)=-2 \sin (p^i \theta)\cdot p^i.$$

    Hence, $$Q_{p^i}'(2\cos \theta)= \frac{p^i \sin(p^i \theta)}{\sin \theta},$$ and the result follows from Lemma \ref{R'p-1}.
\end{proof}




Let $n=a_sp^{s}+a_{s-1}p^{s-1}+ \cdots + a_0$. Then $$Z_n(t)=\frac{t^{n-1}\prod_{i=0}^s\widehat{R}_{p-a_i-1,\ i}(t)}{\prod_{i=0}^s\widehat{R}_{p-1,\ i}(t)}.$$ 
Let $A_n(t)=\prod_{i=0}^sR_{p-a_i-1,\ i}(t)$ and $B_n(t)= \prod_{i=0}^s R_{p-1,\ i}(t),$ of degree $\sum_{i=0}^s (p-a_i-1)p^{i}=p^{s+1}-1-n$ and $\sum_{i=0}^s (p-1)p^{i}=p^{s+1}-1$ respectively.



\begin{prop} \label{m_ninbeta}

        Suppose $l \ge n-1+ \deg A_n(t)=
        p^{s+1}-2.$ Then $$\m_{n-1}(x^l)=\sum_{\{\b \mid B_n(\b)=0\}}\frac{A_n(\b)}{B_n'(\b)}\b^l.$$ In fact, 
        \begin{equation*}
        \m_{n-1}(x^l)=\begin{dcases}
            2 \sum_{\{\b \mid B_n(\b)=0 \text{ and $\b>0$}\}}\frac{A_n(\b)}{B_n'(\b)}\b^l \quad \text{if $n-1  \equiv l$ (mod $2$)}\\
            0\qquad \qquad \qquad \qquad \quad \ \   \text{if $n-1 \not \equiv l$ (mod $2$)}.
        \end{dcases}
    \end{equation*}

\end{prop}

\begin{proof}
    By Lemma \ref{g/fhat}, \begin{align*}
        \m_{n-1}(x^l)&=\sum_{\{\b \mid B_n(\b)=0\}} \frac{\b^{p^{s+1}-2}}{B_n'(\b)}\b^{1-n} \prod_{i=0}^s\widehat{R}_{p-a_i-1,\ i}(\b^{-1})\b^l\\
        &=\sum_{\{\b \mid B_n(\b)=0\}} \frac{\b^{p^{s+1}-1-n}}{B_n'(\b)} \prod_{i=0}^s\widehat{R}_{p-a_i-1,\ i}(\b^{-1})\b^l.        
    \end{align*}

    As $$f(t)=\hat{\hat{f}}(t)=t^{\deg \hat{f}}\hat{f}(1/t)=t^{\deg f}\hat{f}(1/t)$$ and $$\deg A_n=p^{s+1}-1-n,$$ $$\m_{n-1}(x^l)=\sum_{\{\b \mid B_n(\b)=0\}}\frac{A_n(\b)}{B_n'(\b)}\b^l.$$

    Rewrite $\m_{n-1}(x^l)$ as
    \begin{align*}
                \sum_{\{\b \mid B_n(\b)=0 \text{ and } \b>0\}}\frac{A_n(\b)}{B_n'(\b)}\b^l+\sum_{\{\b \mid B_n(\b)=0 \text{ and } \b>0\}}\frac{A_n(-\b)}{B_n'(-\b)}(-\b)^l
    \end{align*}

    Recall $R_{m-1}(2\cos \theta)= \prod_{k=1}^{m-1}(2 \cos \theta - k\pi/m)=2\sin (m (\theta-\pi))/ \sin \theta$.

    As $\b=2 \cos \theta$,  $-\b=-2 \cos \theta=2 \cos (\pi-\theta)$. Since $\sin (\pi-\theta)=\sin \theta$, \begin{align*}
        R_{m-1}(-2\cos \theta)&=R_{m-1}(2 \cos (\pi-\theta))=\frac{2\sin (m ((\pi-\theta)-\pi))}{\sin (\pi-\theta)}\\
        &=\frac{-2 \sin (m\theta)}{ \sin (\pi-\theta)}=\begin{cases}
            R_{m-1}(2 \cos \theta), \qquad \text{when $m$ is odd}\\
            -R_{m-1}(2\cos \theta), \qquad \text{when $m$ is even.}
        \end{cases}
    \end{align*}


    Therefore, $R_{p-a-1}(2 \cos (\pi - \theta))=R_{p-a-1}(2 \cos \theta)$ if and only if $a$ is even.

    As $A_n(t)=\prod_{i=0}^sR_{p-a_i-1,\ i}(t)$, $A_n(2 \cos (\pi-\theta))= (-1)^{\sum_{i=0}^s a_i } A_n (2 \cos \theta)$.


    By Lemma \ref{R_p-1,s'}, $$R_{p-1, i}'(2\cos \theta)= (-1)^k p^{i+1}/2\sin (p^i\theta) \sin \theta$$ where $k=p^{i+1}\theta\pi$, i.e. $p^i \theta=k\pi/p$. 

    As $p^i(\pi-\theta) \equiv \pi-k\pi/p$ (mod $2\pi$), $$R_{p-1, i}'(2 \cos (\pi-\theta))=(-1)^{k+1}p^{i+1}/2\sin (p^i\theta) \sin \theta$$ where the exponent of $-1$ is $k+1$ since $p^i(\pi-\theta) \equiv \pi-k\pi/p=(p-k)\pi/p$ (mod $2\pi$), and $p-k\equiv k+1$ (mod $2$). Therefore, $B_n'(2\cos (\pi-\theta))=-2B_n'(2 \cos \theta).$

    Combine the results for $A_n(t)$, $B_n'(t)$ and $n \equiv \sum_{i=0}^s a_i$ (mod $2$) to obtain

    \begin{equation*}
        \frac{A_n(-\b)}{B_n'(-\b)}=\begin{dcases}
            \frac{A_n(\b)}{B_n'(\b)}  \qquad  \text{if $n$ is odd}\\
            -\frac{A_n(\b)}{B_n'(\b)} \quad \ \text{if $n$ is even}.
        \end{dcases}                  
    \end{equation*}

    Therefore

    \begin{equation*}
        \frac{A_n(-\b)}{B_n'(-\b)}(-\b)^l=\begin{dcases}
            -\frac{A_n(\b)}{B_n'(\b)}\b^l  \qquad  \text{if $n\equiv l$ (mod $2$)}\\
            \frac{A_n(\b)}{B_n'(\b)}\b^l \quad \ \text{if $n\not \equiv l$ (mod $2$)},
        \end{dcases}                  
    \end{equation*}
    and the result follows.
\end{proof}





\begin{lemma} \label{est_R_m-1} Let $0<m\le p$ and $s\in \N$. Let $\theta=\theta_{s, j}=j\pi/p^{s+1}$ for some integer $j$. Then
    \begin{itemize}
        \item [(1)] $\vert \sin \theta \vert \ge \vert \sin \theta_{s,1}\vert \ge 2/p^{s+1}.$
        \item[(2)] $2^p>\vert R_{m-1}(2 \cos \theta) \vert \ge 4/p^{s+1}.$
        \item[(3)] Suppose $\pi/2 > m\theta >0$. Then $2^p\ge\vert R_{m-1}(2 \cos \theta) \vert \ge 2/\pi.$
    \end{itemize}


\end{lemma}

\begin{proof}
Part (1) It follows from the fact that $\theta$ is a multiple of $\pi/ p^{s+1}$ and $\sin x > 2x/\pi $ when $\pi/2>x> 0$.

 (2) As $\sin (m\theta) =2^{m-1} \prod_{k=0}^{m-1} \sin( \theta + k\pi/m)$, one has $\vert \sin (m \theta)/\sin \theta \vert \le 2^{m-1}.$   

From (1), we obtain $\vert \sin (m \theta) \vert > 2/p^{s+1}.$ Therefore,  $$2^p \ge 2^m > \vert R_{m-1}(2 \cos \theta) \vert = \bigg\vert \frac{2\sin(m \theta)}{\sin \theta} \bigg\vert     \ge \vert 2 \sin (m \theta) \vert > 4/p^{s+1}.$$  
\\
(3) Suppose $\pi/2 > m\theta >0$. Then \begin{align*}
    2^p > \vert R_{m-1}(2 \cos \theta) \vert \stackrel{(*)}{>}  \frac{2m\theta/\pi}{\theta}=2m/\pi \ge 2/\pi,  
\end{align*}

where $(*)$ comes from Proposition \ref{R_m-1} and $x \ge \sin x$ for all $x \ge 0$.
\end{proof}


\begin{lemma}   
 \label{estPn}
    Given $s \in \Z_{\ge 0}$ and $(n_1, n_2, \cdots, n_s) \in \N^s$, $p \ge n_i \ge 1$.

    Then $$(2^p)^s \ge  \vert\prod_{i=0}^s R_{n_i-1, i}(2 \cos \theta_{s, j}) \vert \ge \pi^{-(s-1-\log_p j)}2^s p^{-(\log_p j)^2}.  $$
\end{lemma}

\begin{proof}
    Since $\vert R_{m-1}(2 \cos \theta) \vert$ is always bounded above by $2^p$, we get the upper bound.

    The lower bound of $\vert R_{m-1}(2 \cos \theta) \vert$ is separated into the cases $m \theta > \pi/2$ or not.  As $R_{n_i-1, i}=R_{n_i-1}\circ Q_{p^{i}}$, we divide into cases depending on whether $p^{i}n_i \theta_{s,j}> \pi/2$ or not.

    Suppose $p^im \theta_{s, j}>\pi/2$ for some $i<s$ and $p \ge m >0$. Therefore, $$p^imj/p^{s+1}>1/2.$$

    This gives $i+ \log _p mj>s+1-\log_p2.$ Therefore, $i>s+1 - \log_p (2mj).$ There are at most $\lfloor \log_p 2mj \rfloor$ options for such $i$. 

    As $p\ge m \ge 1$,  there are at most $\lfloor \log_p j \rfloor +2$ options: $s-1,\ s-2,\ \cdots,\ s-2-\lfloor \log_p j \rfloor$. Since $\vert \sin (p^{i} m \theta_{s, j}) \vert \ge 2 \frac{p^{i}}{p^{s+1}} $, we have the lower bounds 
    $$2p^{-2},\ 2p^{-3},\ \cdots,\ 2p^{-(3+ \lfloor \log_p j \rfloor )}.$$



    Combining the lower bounds above and Lemma \ref{est_R_m-1} (3), we have $$
    (2^p)^s \ge \vert \prod_{i=0}^s R_{n_i-1, i}(2\cos \theta_{s, j}) \vert \ge \pi^{-(s-\log_pj -1)}2^s p^{-(\log_p j)^2}.    
    $$

\end{proof}

