\begin{prop} \label{m_ninbest}
    Suppose $l < \sum_{i=0}^s (p-1)p^{i}-1=p^{s+1}-2$. Then $$\m_{n-1}(x^l)=\bigg(\sum_{\{\b \mid B_n(\b)=0\}}\frac{A_n(\b)}{B_n'(\b)}+f_l(\b^{-1}) \bigg)\b^l,$$
        for some $f_l(\b^{-1}) \in o(k^{-2-\alpha}(1+\epsilon)^k),$        where $k$ is some large number so that $n < \sqrt{k} \log k$ and  $\alpha$ and $\epsilon$ are any positive number.   
\end{prop}

\begin{proof}
    By Lemma \ref{g/fhat} (2), $$\m_{n-1}(x^l)=\sum_{\{\b \mid B_n(\b)=0\}}\frac{A_n(\b)}{B_n'(\b)}\b^l -\sum_{\{\b \mid B_n(\b)=0\}} \frac{\b^{p^{s+1}-1-n}}{B_n'(\b)}\sum_{{l<i \le d}} c_i \b^{l-i},$$ where $d=p^{s+1}-2$ and $c_i$ is the $t^i$-coefficient of $t^{n-1}\widehat{A}_n(t)$.  We want to show that the latter term is small compared to $k^{-2-\alpha_p}(1+\epsilon)^k$ when $k$ is large. 

    The set of  coefficients of $t^{n-1}\widehat{A}_n(t)$ is the set of  coefficients of $\widehat{A}_n(t)$. By the formula $\hat{f}(t)=t^{\deg f}f(1/t)$, the set of the coefficients of $\widehat{A}_n(t)$ is the set of the coefficients of $A_n(t)$. Since $A_n(t)$ is a polynomial of degree $\sum_{i=0}^s (p-a_i-1)p^{i}<pn=\sum_{i=0}^s a_i p^{i+1}$ with roots of the form $2 \cos \theta$ for some $\theta$, $$\vert c_i \vert < \binom{pn}{pn/2} 2^{pn}.$$

    By Stirling approximation, there exists some $C>0$ so that for each $i$, $$\vert c_i \vert < C \frac{2^{pn}}{\sqrt{pn\pi/2}}2^{pn}.$$

    As $\vert \b \vert =\vert 2 \cos j\pi/p^{s+1}\vert > 4j/p^{s+1},$ one has $\vert \b ^{-1} \vert < p^{s+1}<pn.$ Hence, $$\sum_{{l<i \le d}} \vert c_i \b^{l-i} \vert <  pn (C \frac{4^{pn}}{\sqrt{pn\pi/2}} pn^{pn})=C \frac{4^{pn}}{\sqrt{pn\pi/2}} pn^{pn+1}<C4^{pn}pn^{pn+1}.$$

    Suppose $n< \sqrt{k}\log k $ for some large $k$. We want to show that for any $\alpha>0$ and $\epsilon>0$  \begin{equation} \label{todiscard}
        \sum_{\{\b \mid B_n(\b)=0\}} \frac{\b^{p^{s+1}-1-n}}{B_n'(\b)}\sum_{{l<i \le d}} c_i \b^{-i} \in o(k^{-2-\alpha}(1+\epsilon)^k).
    \end{equation}

    The bound for each term:

    \begin{itemize}
        \item $\vert B_n'(\b) \vert^{-1}:$ By Lemma \ref{estR'}, \begin{align*}
            \vert B_n'(\b) \vert^{-1} \le \bigg(\frac{p^{i_0+1}}{2\sin(k\pi/p)\sin \theta_{s, j}}\pi^{-(s-2-\log_pj )}2^{s-1} p^{-(\log_p j)^2} \bigg)^{-1}\\
            \le 2\pi^{s-\log_p j}2^{1-s}p^{(\log_p j)^2}
        \end{align*}
        for some $j<p^{s+1}<pn.$ Hence $$\vert B_n'(\b) \vert^{-1} \le \pi^s (pn)^{pn} \le \pi^n(pn)^{pn}.$$

        \item $\b^{{p^{s+1}-1-n}} < 2^{pn}$

        \item $\sum_{{l<i \le d}} \vert c_i \b^{l-i} \vert <  C \frac{4^{pn}}{\sqrt{2pn\pi/2}} pn^{pn+1}.$
    \end{itemize} 

    Let $N=\sqrt{k}$. By assumption $n < \sqrt{k}\log k=2N \log N$, we rewrite the bounds in $N$,

    \begin{itemize}
        \item $\vert B_n'(\b) \vert^{-1}< \pi ^{2N \log N}(2pN \log N)^{2pN\log N}$

        \item $\b^{-n+\sum_{i=0}^s(p-1)p^{i}}< 2^{2pN \log N} $

        \item  $\sum_{{l<i \le d}} \vert c_i \b^{l-i} \vert < C4^{2pN\log N}(2pN \log N)^{2p N \log N}$
    \end{itemize}

To show \eqref{todiscard}, it suffices to show 

$$\lim_{k \to \infty} \bigg(\sum_{\{\b \mid B_n(\b)=0\}} \frac{\b^{p^{s+1}-1-n}}{B_n'(\b)}\sum_{{l<i \le d}} c_i \b^{-i}\bigg) (k^{-2-\alpha}(1+\epsilon)^k)^{-1}=0$$

Using the bounds in terms of $N$ and taking the logarithm, it shows that the limit is zero.





\end{proof}

Let $K$ be an algebraically closed field of $\ch$ $p>0$. Denote $\SL_2(K)$ by $G$. Let $V$ denote the natural representation of $G$. As $\text{Tilt($G$)}$,  the ring of virtual tilting modules of $G$, is a subring of the representation ring of $G$, there is a ring homomorphism from $\Z[x] \to \text{Tilt($G$)}$ defined by $Q(x) \mapsto Q(V)$. 

As $t^n+t^{-n}=Q_n(t+t^{-1})$ where $Q_n(x)\in \Z[x]$ is the Chebyshev polynomial of degree $n$, the map $Q(x) \mapsto Q(t+t^{-1})$ gives a ring  isomorphism from $\Z[x]$ to $\Z[t, t^{-1}]^{\Z/2\Z}$, the invariant subring  of $\Z[t, t^{-1}]$ where the non-trivial element of $\Z/2\Z$ sends $t$ to $t^{-1}$. 

Given any tilting module $T$, since $\chi_T(t)$, the formal character of $T$, is an element of $\Z[t, t^{-1}]^{\Z/2\Z}$, it follows that $\chi_T(t)=Q(t+t^{-1})$ for some unique $Q(x) \in \Z[x]$. As the formal character of $Q(V)$ is $Q(t+t^{-1})=\chi_V(t)$ and the tilting modules are determined by their formal characters, $Q(V)=T$. Hence, the ring $\Z[x]$ is isomorphic to the ring $\text{Tilt($G$)}.$

We modify Lemma 6.2 from   \cite{larsen2024boundsmathrmsl2indecomposablestensorpowers} which deals with the case $p=2$ to the case $p>2$.

\begin{lemma} \label{lemma_p}
    Suppose $K$ is of characteristic $p>2.$ Let $T$ be a tilting representation of $G$ and $Q(x)\in \Z[x]$ such that $Q(V)=T.$
    Then
    \begin{itemize}
        \item [(1)] $Q(2)=\dim T$
        \item [(2)] $Q'(2)>0$
        \item[(3)] $\vert Q(x) \vert < \dim T$ for all $x \in (-2, 2)$
        \item[(4)] $\vert Q(-2) \vert =\dim T$ if and only if $T$ is purely even or purely odd, i.e., a direct sum of tilting representations whose highest weights are all even or all odd. More precisely, if $Q(-2)=\dim T$ ($Q(-2)=-\dim T$, resp.), then $T= \oplus_mT(m)$ for some even (odd, resp.) $m$. 
    \end{itemize}
\end{lemma}
\begin{proof}
    For (4), we note that by the character formula $\eqref{char_n}$, the form of elements in $\supp (n)$, and $2p^s \equiv 0$ (mod $2$), it follows that when we write $\chi_n(t)=\sum_m a_mt^m$ where $a_m \neq 0$, all the $m$ are even if $n$ is even, and all $m$ are odd if $n$ is odd. With this observation, (1)--(4) follow as in \cite{larsen2024boundsmathrmsl2indecomposablestensorpowers}.  



\end{proof}



\begin{thm}
    Let $K$, $T$ and $Q(x)$ be as in the above lemma. Then for each $T$, there exists some positive numbers $C_T$ and $D_T$ such that when $k$ is sufficiently large, 

    \begin{equation} \label{main_ineq}
        C_Tk^{-\alpha_p} (\dim T)^k < b_k^{G, T}< D_T k^{-\alpha_p}(\dim T)^k    
    \end{equation}
    where $\alpha_p=1-(1/2)\log_p(\frac{p+1}{2})$.    

\end{thm}

\begin{proof}
    We may assume $\deg Q(x)>0$, i.e, $T$ is not a direct sum of the trivial representations; otherwise, $b_k^{G, T}=(\dim T)^k.$  We treat the case that $\vert Q(-2) \vert \neq \dim T$ first. Then we prove the case $\vert Q(-2) \vert = \dim T$.

    The formal character of $T$ is $Q(t+t^{-1})$ and the formal character of $T^{\xx k}$ is $Q(t+t^{-1})^k$. We will use Hoeffding's inequality to show that the space
    \begin{equation*}
        W=\langle v \mid v \text{ is a weight vector with a weight higher than $\sqrt{k}\log k$ } \rangle_K
    \end{equation*}
    is of dimension smaller than $(\dim T)^k\exp( -C (\log k)^2)$ for some  $C>0$. Since the weight $n$ subspace of $T(n)$ is of dimension $1$, it follows that $$\sum_{n> \sqrt{k}\log k } \m_n (Q(x)^k)<(\dim T)^k\exp( -C (\log k)^2).$$ Therefore, to prove the theorem, it suffices to show that $$\sum_{n< \sqrt{k}\log k } \m_n (Q(x)^k)$$ have an upper bound and a lower bound of the form in \eqref{main_ineq}.

    Write the formal character of $T$ as $\sum_{-d \le i \le d} a_i t^i$.  Let $X_i,\ \cdots,\ X_k$ be i.d.d. random variables, with outcomes $-d\le j\le d$ with probability $a_j/\dim T$ . Let $S_k=\sum_{i=1}^k X_i$ and $E_k$ be the expected value. The expected value $E_k=0$ by its definition. By Hoeffding's inequality, \begin{align*}
        \text{Pr } \big[  S_n > \sqrt{k}\log k \big] &\le  \exp (-2k(\log k)^2/4d^2k) \\
        &<\exp(-C(\log k)^2)
    \end{align*}
 for some $C>0.$
    Hence $$\dim W < (\dim T)^k\exp( -C (\log k)^2).$$ 



    As the map $\m_n$ is additive and by Lemma \ref{g/fhat}, $\m_{n-1}(Q(x)^k)=\sum_j a_{n, j}Q(\b_{n, j})^k$ for some $a_{n,j}.$ 

    For any $\alpha>0$, by Proposition \ref{m_ninbeta} and Proposition \ref{m_ninbest},  we have
     \begin{align*}
        \sum_{n< k \log k} \m_{n-1}(Q(x)^k)&=\sum_{n< k \log k} \sum_{\{j \mid B_n(\b_{n, j})=0\}} a_{n, j}Q(\b_{n, j})^k\\
        &=\sum_{n< k \log k} \sum_{\{j \mid B_n(\b_{n, j})=0\}}\Big( c_{n, j}Q(\b_{n, j})^k  +o(k^{-2-\alpha} (\dim T)^k )\Big)
    \end{align*}

    where $c_{n, j}=A_n(\b_{n,j})/B_n'(\b_{n,j})$, $A_n(t)$, $B_n(t)$ are as in Proposition \ref{m_ninbeta}, and $\b_{n, j}=2\cos \theta_{n, j}$.



    By Lemma \ref{lemma_p}, $Q'(2)>0$ and $\vert Q(x) \vert < \dim T$ for $x \in (-2, 2)$. 

    Let $\delta >0$. Since $\vert Q(-2) \vert \neq \dim T,$  $\max _{\{x\in [-2, 2-\delta]\}} \vert Q(x) \vert < \dim T$. Therefore,  for any $\b\in [-2, 2-\delta]$, $\vert Q(\b) \vert < (1-\epsilon)\dim T$ for some $\epsilon>0.$ Hence, for those angles $\theta_{n, j}$ not small enough, $\vert Q(\b_{n, j})^k \vert < (1-\epsilon)^k(\dim T)^k.$ 



    A calculation similar to Proposition \ref{m_ninbest} gives that $c_{n, j}\in o(k^{-2-\alpha}(1+\delta')^k)$ for any $\delta'>0$ Hence, $c_{n, j}Q(b_{n, j})^k \in o(k^{-2-\alpha} (\dim T)^k )$ for any $\b_{n, j}\in [-2, 2-\delta].$


    Now we take $\delta=\log k/k>0$ and we may assume $\b_{n, j}\in (2-\delta, 2).$

    By Taylor's Theorem for $Q(x)$ at $x=2$ and $\log(1+x)$ at $x=0$,   \begin{equation}
        Q(\b_{n, j})=\dim T - Q'(2) (2- \b_{n, j})+ O(\delta^2) 
    \end{equation}
    so
    \begin{equation} \label{choosel}
        k(\log Q(\b_{n,j})- \log \dim T )=l(\log \b_{n, j}- \log 2)+O((\log^2 k)/k)
    \end{equation}
where $l=\lfloor 2kQ'(2)/ \dim T \rfloor$ or $\lfloor 2kQ'(2)/ \dim T \rfloor+1$ depending on the desired parity of $l$.


Therefore, \begin{equation} \label{M_k}
    \bigg(\frac{Q(\b_{n, j})}{\dim T} \bigg)^k=\big(\frac{\b_{n, j}}{2} \big)^l \cdot M_k
\end{equation}
    for some $M_k$ where $\lim_{k \to \infty} M_k=1.$


    As $\m_{n-1}(Q(x)^k)= \sum_j \Big(c_{n, j} Q(\b_{n, j})^k+o(k^{-2-\alpha}(\dim T)^k)\Big)$, we have 
    \begin{align*}
        \m_{n-1}(Q(x)^k) &= \bigg (\sum_{\{ j \mid \b_{n,j} \in (2-\delta, 2)  \}}  c_{n,j} Q(\b_{n, j})^k \bigg) +o(k^{-1-\alpha}(\dim T)^k)\\
        &=\bigg( (\dim T)^k (2^{-l})M_k \sum_{\{ j \mid \b_{n,j} \in (2-\delta, 2)  \}} c_{n, j}(\b_{n, j})^l \bigg) +o(k^{-1-\alpha}(\dim T)^k).        
    \end{align*}


For each $n$, we choose $l$ in \eqref{choosel} so that $l$ and $n-1$ have the same parity. Since $l \equiv n-1$ (mod $2$),  by Proposition \ref{m_ninbeta}, $$\m_{n-1}(Q(x)^k)= 1/2(\dim T)^k (2^{-l})M_k \cdot \m_{n-1}(x^l) +o(k^{-1-\alpha}(\dim T)^k).$$



Then \begin{align*}
    b_k^{G, T}&=\sum_n \m_{n-1}(Q(x)^k)\\
    &=\sum_{\text{$n$ is odd}} \m_{n-1}(Q(x)^k)  +\sum_{\text{$n$ is even}} \m_{n-1}(Q(x)^k) \\
     &= \bigg( 1/2(\dim T)^k (2^{-l})M_k \sum_{\text{$n$ is odd}} \m_{n-1}(x^l) +  1/2(\dim T)^k (2^{-(l+1)})M_k \sum_{\text{$n$ is even}} \m_{n-1}(x^{l+1}) \bigg) +o(k^{-\alpha}(\dim T)^k)\\
     &=  \bigg( 1/2(\dim T)^k (2^{-l})M_k \sum_{n \in \N} \m_{n-1}(x^l) +  1/2(\dim T)^k (2^{-(l+1)})M_k \sum_{n \in \N} \m_{n-1}(x^{l+1}) \bigg) +o(k^{-\alpha}(\dim T)^k).   
\end{align*}



By \cite[, Main Theorem 1B.8]{coulembier2024fractalbehaviortensorpowers},

\begin{equation*}
    Cl^{-\alpha_p}2^l < \sum_{ n< \sqrt{l}\log l } \m_n(x^l) < D l^{-\alpha_p} 2^l
\end{equation*}
where $\alpha_p=1-(\log_p \frac{p+1}{2})/2.$


Therefore,

\begin{equation*}
    (1/2)CM_k (l^{-\alpha_p}+(l+1)^{-\alpha_p}) (\dim T)^k <  \sum_{ n< \sqrt{k}\log k } \m_n(Q(x)^k)<(1/2)DM_k (l^{-\alpha_p}+(l+1)^{-\alpha_p})(\dim T)^k.
\end{equation*}
Set $C_T^k=(1/2)CM_k (l^{-\alpha_p}+(l+1)^{-\alpha_p})k^{\alpha_p}$ and $D_T^k=(1/2)DM_k (l^{-\alpha_p}+(l+1)^{-\alpha_p})k^{\alpha_p}$. Let $C'_T=\lim_{k \to \infty} C_T^k$  and $D'_T=\lim_{k \to \infty} D_T^k$. The limits exist since 
$\lim_{k \to \infty}M_k =1$ and $\lim_{k \to \infty}l/k=2Q'(2) / \dim T$ by the definition of $l$.

Let $C_T=C'_T - \epsilon$ and $D_T=D'_T + \epsilon$ for an arbitrary $\epsilon>0$.

Then

\begin{equation*}
    C_Tk^{-\alpha_p}(\dim T)^k <  \sum_{ n< \sqrt{k}\log k } \m_n(Q(x)^k)< D_T k^{-\alpha_p}(\dim T)^k,
\end{equation*}
so the result of the  case $\vert Q(-2)\vert \neq \dim T$ is proved.


\vspace{5mm}
\par
    Suppose $\vert Q(-2) \vert =\dim T$. Then $Q(x)$ is either an even or an odd polynomial. As the functions $\m_n$ are additive, by Proposition \ref{m_ninbeta} \begin{align*}
        \m_{n-1}(Q(x)^k)\equiv\begin{dcases}
            2 \sum_{\{j \mid B_n(\b_{n, j})=0 \text{ and $\b_{n, j} >0$}\}}c_{n, j }Q(b_{n, j})^k \quad \text{if $n-1  \equiv k \deg Q(x)$ (mod $2$)}\\
            0\qquad \qquad \qquad \qquad \quad \ \   \text{if $n-1 \not \equiv k \deg Q(x)$ (mod $2$)}.
        \end{dcases}
    \end{align*}
    (mod $o(k^{-2-\alpha} (\dim T)^k ))$.

    When taking $l$ in \eqref{choosel}, we choose $l$ so that the parity of $l$ is the same as the parity of the polynomial $Q(x)^k$, i.e. $l \equiv k$ (mod $2$) if $Q(x)$ is odd, and $l$ is even if $Q(x)$ is even. 

    Since $l$ and $Q(x)^k$ have the same parity, by \eqref{M_k}, $$\m_{n-1}(Q(x)^k)= (\dim T)^k 2^{-l}M_k \cdot \m_{n-1}(x^l) +o(k^{-1-\alpha}(\dim T)^k),$$ and the result follows.
\end{proof}



